def maxPrimes(n, s):
    # sieve of Eratosthenes: is_prime[p] == 1 when p is prime
    is_prime = bytearray([1]) * (n + 1)
    is_prime[0] = 0
    if n >= 1:
        is_prime[1] = 0
    i = 2
    while i * i <= n:
        if is_prime[i]:
            # cross out multiples of i starting at i * i
            for j in range(i * i, n + 1, i):
                is_prime[j] = 0
        i += 1

    selected = []
    total = 0
    # greedy: take the smallest primes while the budget allows
    for p in range(2, n + 1):
        if is_prime[p]:
            if total + p > s:
                break  # every later prime is even larger, so stop
            total += p
            selected.append(p)

    return selected
